import os
import shutil
from typing import List


class LogPurpose(object):
    def __init__(self, logs_paths: List[str]):
        self.logs_paths = logs_paths

    def extra_preparation(self) -> List[str]:
        return self.logs_paths  # does nothing by default


class CNI_86663(LogPurpose):
    """
    CNI-86663: Log scrambling regression suite improvement to verify scrambling of syslog and SCF file collected outside of snapshot.
    Two scenarios:
    1. Scrambling of the syslog and SCF outside the snapshot (done automatically by scrambling framework).
    2. Verification of the rules for different syslog filename regexes (3 regexes, each of them should have the same set of rules ->
    scrambling of 3 syslogs with different filenames but with an identical content should result in 3 same scrambled files).
    """
    def __init__(self, logs_paths: List[str]):
        super().__init__(logs_paths=logs_paths)

    def extra_preparation(self) -> List[str]:
        """
        1. Find the largest syslog and remove other files (if exist).
        2. Rename it to "master_syslog.log".
        3. Copy it 2 times with the names that follow the regexes mentioned in CNI.
        """
        new_names = ["123456_Syslog_233008_1229.log", "20230830T201600_10.45.178.26_condor5gSyslog_10.45.178.26_Syslog_210913_2016.LOG"]
        new_logs_paths = []
        if "syslog" not in self.logs_paths[0]:
            return self.logs_paths
        main_syslog_path = max(self.logs_paths, key=lambda path: os.path.getsize(path))
        for log_path in self.logs_paths:
            if log_path != main_syslog_path:
                os.remove(log_path)
        dir_path = os.path.dirname(main_syslog_path)
        new_main_syslog_path = os.path.join(dir_path, "master_syslog.log")
        shutil.move(main_syslog_path, new_main_syslog_path)
        new_logs_paths.append(new_main_syslog_path)
        for name in new_names:
            new_name = os.path.join(dir_path, name)
            shutil.copy(new_main_syslog_path, new_name)
            new_logs_paths.append(new_name)

        return new_logs_paths
